import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Optimized CUDA kernel with register blocking
cuda_source = """
#include <torch/extension.h>

#define TILE_SIZE 32
#define BLOCK_SIZE 8  // Each thread computes a 4x4 block

__global__ void matmul_kernel(const float* __restrict__ A, 
                              const float* __restrict__ B, 
                              float* __restrict__ C, 
                              int N) {
    // Shared memory for tiles
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    // Each thread computes a 4x4 block
    const int thread_row = threadIdx.y * 4;
    const int thread_col = threadIdx.x * 4;

    // Global position
    int block_row = blockIdx.y * TILE_SIZE;
    int block_col = blockIdx.x * TILE_SIZE;

    // Register accumulation
    float c_reg[4][4] = {{0}};

    // Loop over tiles
    for (int t = 0; t < N; t += TILE_SIZE) {
        // Load tile from A into shared memory
        int a_row = block_row + threadIdx.y;
        int a_col = t + threadIdx.x;
        if (a_row < N && a_col < N) {
            As[threadIdx.y][threadIdx.x] = A[a_row * N + a_col];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile from B into shared memory
        int b_row = t + threadIdx.y;
        int b_col = block_col + threadIdx.x;
        if (b_row < N && b_col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[b_row * N + b_col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial sum for this tile with register blocking
        for (int k = 0; k < TILE_SIZE; k++) {
            float a_val[4], b_val[4];

            // Prefetch values
            a_val[0] = As[threadIdx.y][k];
            a_val[1] = As[threadIdx.y + BLOCK_SIZE][k];
            a_val[2] = As[threadIdx.y + 2*BLOCK_SIZE][k];
            a_val[3] = As[threadIdx.y + 3*BLOCK_SIZE][k];

            b_val[0] = Bs[k][threadIdx.x];
            b_val[1] = Bs[k][threadIdx.x + BLOCK_SIZE];
            b_val[2] = Bs[k][threadIdx.x + 2*BLOCK_SIZE];
            b_val[3] = Bs[k][threadIdx.x + 3*BLOCK_SIZE];

            // Accumulate results
            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < 4; j++) {
                    c_reg[i][j] += a_val[i] * b_val[j];
                }
            }
        }

        __syncthreads();
    }

    // Write result to global memory
    int row = block_row + thread_row;
    int col = block_col + thread_col;

    if (row < N && col < N) {
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                if (row + i < N && col + j < N) {
                    C[(row + i) * N + (col + j)] = c_reg[i][j];
                }
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Get matrix dimension
    int N = A.size(0);

    // Create output tensor
    auto C = torch::zeros({N, N}, A.options());

    // Configure kernel launch parameters
    dim3 threadsPerBlock(BLOCK_SIZE, BLOCK_SIZE);
    dim3 blocksPerGrid((N + TILE_SIZE - 1) / TILE_SIZE,
                      (N + TILE_SIZE - 1) / TILE_SIZE);

    // Launch kernel
    matmul_kernel<<<blocksPerGrid, threadsPerBlock>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
"""

# C++ wrapper code
